import React, { useRef } from "react";
import { useScroll } from "@react-three/drei";
import { useFrame } from "@react-three/fiber";
import * as THREE from "three";

export const Overlay = () => {
  const scroll = useScroll();
  const textRef = useRef();
  const arrowRef = useRef();

  useFrame((state) => {
    const offset = scroll.offset;

    // 首屏文案淡出
    if (textRef.current) {
      textRef.current.style.opacity =
        1 - THREE.MathUtils.smoothstep(offset, 0, 0.08);
    }

    // 箭头在滚动后迅速淡出
    if (arrowRef.current) {
      const ghost = Math.sin(state.clock.elapsedTime * 2) * 5;
      arrowRef.current.style.transform = `translateX(-50%) translateY(${ghost}px)`;
      arrowRef.current.style.opacity =
        1 - THREE.MathUtils.smoothstep(offset, 0, 0.08);
    }
  });

  return (
    <div
      style={{
        position: "fixed",
        top: 0,
        left: 0,
        width: "100vw",
        height: "100vh",
        pointerEvents: "none",
        color: "#fff",
        zIndex: 100,
      }}
    >
      {/* 文案：SCROLL DOWN，位置下移至 75% 处，靠近箭头 */}
      <div
        ref={textRef}
        style={{
          position: "absolute",
          top: "72%",
          left: "50%",
          transform: "translate(-50%, -50%)",
          textAlign: "center",
        }}
      >
        <p
          style={{
            fontSize: "12px",
            letterSpacing: "0.8em",
            fontWeight: "300",
            margin: 0,
            opacity: 0.8,
            textTransform: "uppercase",
          }}
        >
          Scroll Down
        </p>
      </div>

      {/* 箭头指示器 */}
      <div
        ref={arrowRef}
        style={{
          position: "absolute",
          bottom: "80px",
          left: "50%",
          transform: "translateX(-50%)",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
        }}
      >
        <div
          style={{
            width: "1px",
            height: "40px",
            borderLeft: "1px dashed rgba(255,255,255,0.5)",
          }}
        />
        <div
          style={{
            width: "8px",
            height: "8px",
            borderRight: "1px solid #fff",
            borderBottom: "1px solid #fff",
            transform: "rotate(45deg) translateY(-5px) translateX(-5px)",
          }}
        />
      </div>
    </div>
  );
};
