import React, { useRef, useMemo } from "react";
import { useFrame } from "@react-three/fiber";
import { useScroll } from "@react-three/drei";
import * as THREE from "three";

const NebulaSprite = ({ position, scale, colorMix, speed }) => {
  const meshRef = useRef();
  const scroll = useScroll();

  const nebulaMaterial = useMemo(() => {
    return new THREE.ShaderMaterial({
      transparent: true,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      uniforms: {
        uTime: { value: 0 },
        uColorMix: { value: colorMix },
        uOpacity: { value: 0.8 },
      },
      vertexShader: `
        varying vec2 vUv;
        void main() {
          vUv = uv;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform float uColorMix;
        uniform float uOpacity;
        varying vec2 vUv;
        float hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }
        float noise(vec2 p) {
          vec2 i = floor(p); vec2 f = fract(p);
          float a = hash(i); float b = hash(i + vec2(1.0, 0.0));
          float c = hash(i + vec2(0.0, 1.0)); float d = hash(i + vec2(1.0, 1.0));
          vec2 u = f * f * (3.0 - 2.0 * f);
          return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
        }
        float fbm(vec2 p) {
          float v = 0.0; float a = 0.5;
          for (int i = 0; i < 5; i++) { v += a * noise(p); p *= 2.0; a *= 0.5; }
          return v;
        }
        void main() {
          vec2 uv = vUv - 0.5;
          float t = uTime * 0.05;
          vec2 q = vec2(fbm(uv * 2.5 + t), fbm(uv * 2.5 + vec2(5.2, 1.3)));
          float f = fbm(uv * 3.0 + 4.0 * q);
          float mask = smoothstep(0.5, 0.1, length(uv) + f * 0.25);
          vec3 blue = vec3(0.05, 0.15, 0.4);
          vec3 purple = vec3(0.2, 0.05, 0.3);
          vec3 orange = vec3(0.7, 0.3, 0.15);
          vec3 baseColor = mix(blue, purple, uColorMix);
          vec3 finalColor = mix(baseColor, orange, pow(f, 4.0));
          gl_FragColor = vec4(finalColor * f * 1.8, mask * f * uOpacity);
        }
      `,
    });
  }, [colorMix]);

  useFrame((state) => {
    const offset = scroll.offset;
    nebulaMaterial.uniforms.uTime.value = state.clock.elapsedTime * speed;
    if (meshRef.current) {
      meshRef.current.position.z = position[2] + offset * 8.0;
    }
  });

  return (
    <mesh ref={meshRef} position={position} scale={scale}>
      <planeGeometry args={[1, 1]} />
      <primitive object={nebulaMaterial} attach="material" />
    </mesh>
  );
};

export const NebulaSystem = () => {
  const clouds = useMemo(() => {
    return Array.from({ length: 15 }).map((_, i) => ({
      position: [
        (Math.random() - 0.5) * 80,
        (Math.random() - 0.5) * 50,
        (Math.random() - 0.5) * 40 - 25,
      ],
      scale: 20 + Math.random() * 30,
      colorMix: Math.random(),
      speed: 0.4 + Math.random() * 0.8,
    }));
  }, []);

  return (
    <group>
      {clouds.map((data, i) => (
        <NebulaSprite key={i} {...data} />
      ))}
    </group>
  );
};
