// @ts-nocheck
import React, { Suspense, useRef, useState } from "react";
import { Canvas, useFrame } from "@react-three/fiber";
import {
  ScrollControls,
  Scroll,
  Stars,
  Environment,
  useScroll,
} from "@react-three/drei";
import * as THREE from "three";
import { NebulaSystem } from "./NebulaSystem";
import { Overlay } from "./Overlay";
import "./styles.css";

const CinematicPlanet = () => {
  const scroll = useScroll();
  const meshRef = useRef(null);
  useFrame((state) => {
    if (!meshRef.current) return;
    const offset = scroll.offset;
    const progress = THREE.MathUtils.smoothstep(offset, 0.1, 0.7);
    meshRef.current.scale.setScalar(THREE.MathUtils.lerp(4, 25, progress));
    meshRef.current.position.y = THREE.MathUtils.lerp(0, -22, progress);
    meshRef.current.rotation.y = state.clock.elapsedTime * 0.05;
  });
  return (
    <mesh ref={meshRef}>
      <sphereGeometry args={[1, 64, 64]} />
      <meshStandardMaterial color="#000" metalness={1} roughness={0.06} />
    </mesh>
  );
};

const CameraRig = () => {
  const scroll = useScroll();
  useFrame((state) => {
    const offset = scroll.offset;
    const angle = THREE.MathUtils.smoothstep(offset, 0, 0.8) * Math.PI * 1.5;
    const radius = 25 + THREE.MathUtils.smoothstep(offset, 0.1, 0.7) * 12;
    state.camera.position.x = Math.sin(angle) * radius;
    state.camera.position.z = Math.cos(angle) * radius;
    state.camera.lookAt(0, -offset * 12, 0);
  });
  return null;
};

// 监听滚动并将 offset 传回 App 组件
const ScrollTracker = ({ setOffset }) => {
  const scroll = useScroll();
  useFrame(() => {
    setOffset(scroll.offset);
  });
  return null;
};

// 纯 HTML 文本组件
const GlowingText = ({ title, content, visible, isBrand }) => {
  return (
    <div className={`ui-text-block ${visible ? "active" : ""}`}>
      {isBrand ? (
        <h2 className="glow-title brand">
          QX <span className="labs">labs</span>
        </h2>
      ) : (
        <h2 className="glow-title">{title}</h2>
      )}
      <p className="glow-content">{content}</p>
    </div>
  );
};

export default function App() {
  const [offset, setOffset] = useState(0);

  // 定义显示区间
  const isVisible = (s, e) => offset > s && offset < e;

  return (
    <div className="main-container">
      {/* 3D 渲染层 */}
      <div className="canvas-layer">
        <Canvas camera={{ position: [0, 0, 25], fov: 40 }} dpr={[1, 2]}>
          <Suspense fallback={null}>
            <Environment preset="night" />
            <Stars radius={200} count={8000} factor={4} fade speed={1} />
            <ScrollControls pages={14} damping={0.3}>
              <ScrollTracker setOffset={setOffset} />
              <CameraRig />
              <NebulaSystem />
              <CinematicPlanet />
              <Scroll html>
                <Overlay />
                <div style={{ height: "1400vh" }} />
              </Scroll>
            </ScrollControls>
          </Suspense>
        </Canvas>
      </div>

      {/* 独立 UI 层：绝对置顶且永远居中 */}
      <div className="ui-overlay-fixed">
        <GlowingText
          visible={isVisible(0.05, 0.2)}
          isBrand={true}
          content="咸休全息决策实验室，融合东西方智慧，探索量化交易的全息决策之道。"
        />
        <GlowingText
          visible={isVisible(0.23, 0.38)}
          title="量化交易"
          content="专注中国A股、ETF、期货市场的量化策略研究"
        />
        <GlowingText
          visible={isVisible(0.41, 0.56)}
          title="交易哲学"
          content="探索交易本质与市场规律的哲学思辨"
        />
        <GlowingText
          visible={isVisible(0.59, 0.74)}
          title="交易技术"
          content="先进算法与系统的研发与实践"
        />
        <GlowingText
          visible={isVisible(0.77, 0.95)}
          title="东⻄⽅决策"
          content="融合东⽅智慧与⻄⽅科学的决策⽅法"
        />
      </div>
    </div>
  );
}
